/// <summary>
/// Form Data Source extension MarkupAutoSetup/MarkupAutoTable
/// MPJ_24248 Pricing Data Extract
/// </summary>
[ExtensionOf(formDataSourceStr(MarkupAutoSetup, MarkupAutoTable))]
final class METMarkupAutoSetupFormDS_MarkupAutoTable_Extension
{
}

Method.Source:
    /// <summary>
    /// COC Active
    /// </summary>
    /// <returns>Integer</returns>
    public int active()
    {
        FormButtonGroupControl  buttonGroupcontrol;
        FormRun metFormRun;
        int     ret;

        if (this.metIsGupCustMarkupAutoSetup())
        {
            //on change of record default Form and controls back to non-edit
            metFormRun = this.formRun() as FormRun;

            metFormRun.viewEditModeHelper().setViewEditMode(ViewEditMode::View);

            metFormRun.metUpdateControls(false);
        }

        ret =  next active();

        return ret;
    }

/// <summary>
/// Is this a Markup record
/// </summary>
/// <returns>True false if its a Markup record</returns>
public boolean metIsGupCustMarkupAutoSetup()
{
    return (this.formRun().args().parmEnum() == MarkupModuleType::Cust &&
            this.formRun().args().menuItemName() == menuItemDisplayStr(GUPMarkupAutoSetup_Cust));
}
